import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"配置运行环境访问入口","description":"在运行概览中设置环境统一入口、证书与端口，核对运行节点和实际工程访问，不混淆平台登录入口。","frontmatter":{"title":"配置运行环境访问入口","description":"在运行概览中设置环境统一入口、证书与端口，核对运行节点和实际工程访问，不混淆平台登录入口。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/environment-entry.md","filePath":"zh/使用指南/配置运行环境访问入口.md"}'),d={name:"zh/guide/environment-entry.md"};function n(i,t,h,s,p,_){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="配置运行环境访问入口" tabindex="-1">配置运行环境访问入口 <a class="header-anchor" href="#配置运行环境访问入口" aria-label="Permalink to &quot;配置运行环境访问入口&quot;">​</a></h1><p>本页设置运行环境中工程应用的<strong>统一访问地址</strong>，不是修改平台安装时的公共入口和管理入口。</p><p>由组织管理员或运维人员进入 <strong>“运维管理” → “运行概览”</strong>，选择正确环境，打开 <strong>“访问入口”</strong>。开始前应准备已就绪基础服务、可访问的网络、未占用端口和需要的证书。</p><h2 id="_1-核对运行节点" tabindex="-1">1. 核对运行节点 <a class="header-anchor" href="#_1-核对运行节点" aria-label="Permalink to &quot;1. 核对运行节点&quot;">​</a></h2><p>页面显示入口的“运行节点”，它由基础服务部署时确定，不能仅因另一台节点在线就认为入口已自动迁移。</p><p>没有入口节点时，按提示先准备基础服务中的代理入口。不要为修复一个地址直接重建全部基础服务，重建可能清空数据。</p><h2 id="_2-启用并填写" tabindex="-1">2. 启用并填写 <a class="header-anchor" href="#_2-启用并填写" aria-label="Permalink to &quot;2. 启用并填写&quot;">​</a></h2><p>打开 <strong>“启用访问入口”</strong>，核对：</p><table tabindex="0"><thead><tr><th>内容</th><th>需要确认</th></tr></thead><tbody><tr><td>访问方式</td><td>HTTP 或 HTTPS，按实际网络和安全要求选择</td></tr><tr><td>访问端口</td><td>页面范围 1024–65535，且未被其他服务占用</td></tr><tr><td>安全证书</td><td>HTTPS 可由平台生成，或上传配套证书与私钥</td></tr><tr><td>节点与网络</td><td>使用者能访问入口所在节点的实际地址和端口</td></tr></tbody></table><p>上传采用配套 PEM 文件，单个不超过 128 KB。不更新已有证书时按提示保留；更新时同时准备证书和私钥，不把私钥放进公开资料或 AI 对话。</p><p>平台生成的证书可能产生信任提示，应由维护人员核对地址与证书后处理，不直接要求所有使用者关闭浏览器校验。</p><h2 id="_3-保存后等待观测" tabindex="-1">3. 保存后等待观测 <a class="header-anchor" href="#_3-保存后等待观测" aria-label="Permalink to &quot;3. 保存后等待观测&quot;">​</a></h2><p>点击 <strong>“保存”</strong>，检查“当前状态”“入口地址”“最近更新”和证书到期信息。</p><p>配置已保存、正在准备和可用要分开判断。显示暂不可用、观测未更新或节点离线时先查具体原因，不拿缓存地址当成可访问证明。</p><h2 id="_4-让工程使用该入口" tabindex="-1">4. 让工程使用该入口 <a class="header-anchor" href="#_4-让工程使用该入口" aria-label="Permalink to &quot;4. 让工程使用该入口&quot;">​</a></h2><p>在工程部署中启用 <strong>“环境入口”</strong>。如果部署只选择“节点直连”，并不会因为环境入口已创建就自动改成统一入口访问。</p><p>从入口面板的“使用此入口的工程”，或部署列表的环境入口链接打开实际应用，核对工程路径、页面登录和业务结果。</p><p>统一入口和节点直连可以同时启用，分别检查。关闭统一入口不会替你打开独立访问，也不会授予工程用户权限。</p><h2 id="_5-调整前先通知" tabindex="-1">5. 调整前先通知 <a class="header-anchor" href="#_5-调整前先通知" aria-label="Permalink to &quot;5. 调整前先通知&quot;">​</a></h2><p>停用入口会让依赖它的工程地址无法访问；更改协议、端口或证书也可能影响正在使用的客户端。操作前通知负责人，保存后逐一核对受影响工程。</p><p>不能访问时先区分入口节点、路由、证书、工程运行、实际访问开关与用户权限，不连续重建平台或关闭安全设置。</p><p>下一步：<a href="/induframe-docs/zh/guide/deployments.html">工程部署</a> · <a href="/induframe-docs/zh/guide/runtime-data-troubleshooting.html">数据链路排查</a>。</p>',22)])])}const u=a(d,[["render",n]]);export{c as __pageData,u as default};
